// RopeConfig 单根钢丝绳配置
type RopeConfig struct {
	RopeID     string
	RopeAreaMM2 float64 // 金属截面积 mm²
}

// Service 监控核心服务
type Service struct {
	dao   *timeseries_dao.DAO
	bus   *alert_service.Bus
	thresh fatigue_calculator.Thresholds

	mu    sync.RWMutex
	calcs map[string]*fatigue_calculator.Calculator
