		select {
		case <-ctx.Done():
			return
		case r := <-readings:
			s.process(ctx, r)
		}
	}
}

func (s *Service) process(ctx context.Context, r opcua_client.Reading) {
	s.mu.RLock()
	calc, ok := s.calcs[r.RopeID]
	s.mu.RUnlock()
	if !ok {
		return
	}

	// PLC 上报的是累计循环数, 差分得到本批次增量
