	if err := s.dao.InsertLoadSample(ctx, timeseries_dao.LoadSample{
		Time: r.Timestamp, RopeID: r.RopeID, LoadKN: r.LoadKN, Cycles: delta,
	}); err != nil {
		log.Printf("[monitor] 写入载荷采样失败: %v", err)
	}
